/**
 * Post-extract portfolio runtime patches (T0.1).
 *
 * Run after extract-portfolio-v25.mjs (or alone on the current runtime):
 *   node scripts/patch-portfolio-runtime.mjs
 *
 * Idempotent. Contains:
 *  - empty-collection / null-safety guards (from patch-portfolio-v25-empty-guards.mjs)
 *  - live lifecycle bridge (scripts/portfolio-runtime-live-bridge.inc.js)
 *  - capital-call / LP form + notices UI tweaks
 *  - IC vote data attrs, NaN guards, recipient harden helpers
 *
 * Hand-edited branches in lib/portfolio-v11-mock/nav.ts are NOT regenerated by
 * extract — keep them in source control; documented in the gap plan.
 */
import fs from "fs"
import path from "path"
import { fileURLToPath } from "url"
import { spawnSync } from "child_process"

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.join(__dirname, "..")
const RUNTIME = path.join(ROOT, "components/portfolio-v11-mock/matanho-portfolio-runtime.js")
const BRIDGE = path.join(ROOT, "scripts/portfolio-runtime-live-bridge.inc.js")
const EMPTY_GUARDS = path.join(ROOT, "scripts/patch-portfolio-v25-empty-guards.mjs")

function must(cond, msg) {
  if (!cond) throw new Error(msg)
}

function replaceOnce(src, find, repl, label) {
  if (!src.includes(find)) {
    if (src.includes(repl) || (label && src.includes(`/* patched:${label} */`))) {
      console.log("skip (already)", label || find.slice(0, 48))
      return src
    }
    console.warn("MISS", label || find.slice(0, 80))
    return src
  }
  return src.replace(find, repl)
}

function replaceAllSafe(src, find, repl, label) {
  if (!src.includes(find)) {
    console.log("skip", label || find.slice(0, 48))
    return src
  }
  return src.replaceAll(find, repl)
}

// 1) Empty guards (existing script)
if (fs.existsSync(EMPTY_GUARDS)) {
  const r = spawnSync(process.execPath, [EMPTY_GUARDS], { cwd: ROOT, encoding: "utf8" })
  if (r.stdout) process.stdout.write(r.stdout)
  if (r.status !== 0) {
    console.warn("empty-guards exited", r.status, r.stderr)
  }
}

let s = fs.readFileSync(RUNTIME, "utf8")
must(s.includes("window.MatanhoPortfolioUI"), "runtime missing MatanhoPortfolioUI marker")

// 2) Inject / refresh live bridge
const bridgeRaw = fs.readFileSync(BRIDGE, "utf8")
const bridgeBody = bridgeRaw
  .replace(/^[\s\S]*?\/\* BEGIN_PORTFOLIO_LIVE_BRIDGE \*\//, "")
  .replace(/\/\* END_PORTFOLIO_LIVE_BRIDGE \*\/[\s\S]*$/, "")
  .trim()

const bridgeBlock = `\n  /* BEGIN_PORTFOLIO_LIVE_BRIDGE */\n${bridgeBody}\n  /* END_PORTFOLIO_LIVE_BRIDGE */\n\n  `

if (s.includes("/* BEGIN_PORTFOLIO_LIVE_BRIDGE */")) {
  s = s.replace(
    /\/\* BEGIN_PORTFOLIO_LIVE_BRIDGE \*\/[\s\S]*?\/\* END_PORTFOLIO_LIVE_BRIDGE \*\/\s*/,
    bridgeBlock,
  )
  console.log("refreshed live bridge")
} else {
  s = s.replace(
    "  window.MatanhoPortfolioUI = Object.freeze({",
    bridgeBlock + "  window.MatanhoPortfolioUI = Object.freeze({",
  )
  console.log("injected live bridge")
}

// 3) Capital call modal — fund options carry id (value=id, label=name)
s = replaceOnce(
  s,
  "<select name=\"fund\">${funds.map(f=>`<option>${escapeHTML(f.name)}</option>`).join('')}</select>",
  "<select name=\"fund\">${funds.map(f=>`<option value=\"${escapeHTML(f.id||f.name)}\">${escapeHTML(f.name)}</option>`).join('')}</select>",
  "capital-call-fund-options",
)

// Also LP / company fund selects that share the same pattern in showCapitalCallModal only — already done if unique.

// 4) Capital call detail — add Send notices button
s = replaceOnce(
  s,
  "${button('Preview notice','preview-capital-call','','eye')}${button('Submit for approval','submit-capital-call-approval','primary','send')}",
  "${button('Preview notice','preview-capital-call','','eye')}${button('Send notices','send-capital-call-notices','','send',`data-id=\"${escapeHTML(call.id)}\"`)}${button('Submit for approval','submit-capital-call-approval','primary','send')}",
  "send-notices-btn",
)

// 5) IC overview vote buttons — attach deal id
s = replaceOnce(
  s,
  "${button('Approve','vote-approve','success compact','check')}${button('Approve with conditions','vote-conditions','compact','shield')}${button('Defer','vote-defer','compact','clock')}${button('Reject','vote-reject','danger compact','x')}",
  "${button('Approve','vote-approve','success compact','check',`data-deal-id=\"${escapeHTML(deal.id)}\"`)}${button('Approve with conditions','vote-conditions','compact','shield',`data-deal-id=\"${escapeHTML(deal.id)}\"`)}${button('Defer','vote-defer','compact','clock',`data-deal-id=\"${escapeHTML(deal.id)}\"`)}${button('Reject','vote-reject','danger compact','x',`data-deal-id=\"${escapeHTML(deal.id)}\"`)}",
  "ic-vote-deal-attrs",
)

// 6) Deal detail header — Launch investee portal when live-ish
s = replaceOnce(
  s,
  "const actions = `${selectControl('Fund',funds.map(f=>f.name),deal.fund,'deal-fund')}${button('Back to Deal Flow','back-to-deals','','arrow-left')}${button('Activity','activity-menu','','clock',`data-context=\"deal\" data-id=\"${deal.id}\"`)}`;",
  "const actions = `${selectControl('Fund',funds.map(f=>f.name),deal.fund,'deal-fund')}${button('Back to Deal Flow','back-to-deals','','arrow-left')}${button('Launch investee portal','open-investee-portal','','external-link',`data-deal-id=\"${escapeHTML(deal.id)}\"`)}${button('Activity','activity-menu','','clock',`data-context=\"deal\" data-id=\"${deal.id}\"`)}`;",
  "deal-header-investee",
)

// 7) NaN guards — reconciliation average
s = replaceOnce(
  s,
  "const matched=sum(reconciliationBatches,r=>r.matched)/reconciliationBatches.length;",
  "const matched=reconciliationBatches.length?sum(reconciliationBatches,r=>r.matched)/reconciliationBatches.length:0;",
  "recon-nan-guard",
)

// Companies averages
s = replaceAllSafe(
  s,
  "sum(companies,c=>c.revenueGrowth)/companies.length",
  "(companies.length?sum(companies,c=>c.revenueGrowth)/companies.length:0)",
  "companies-growth-nan",
)
s = replaceAllSafe(
  s,
  "sum(companies,c=>c.margin)/companies.length",
  "(companies.length?sum(companies,c=>c.margin)/companies.length:0)",
  "companies-margin-nan",
)
s = replaceAllSafe(
  s,
  "sum(companies,c=>c.health)/companies.length",
  "(companies.length?sum(companies,c=>c.health)/companies.length:0)",
  "companies-health-nan",
)
s = replaceAllSafe(
  s,
  "pct(atRisk/companies.length*100)",
  "pct(companies.length?atRisk/companies.length*100:0)",
  "companies-atrisk-nan",
)

// 8) Mailer list blank fields — defensive defaults in row renderer
s = replaceOnce(
  s,
  "escapeHTML(list.description)",
  "escapeHTML(list.description||list.source||'')",
  "mailer-description",
)
// owner may appear multiple times — replaceAll for list.owner in mailer context is risky;
// adapter will supply owner. Still harden common template:
s = replaceAllSafe(
  s,
  "escapeHTML(list.owner)",
  "escapeHTML(list.owner||'—')",
  "mailer-owner",
)
s = replaceAllSafe(
  s,
  "list.channels.join(",
  "(list.channels||['Email']).join(",
  "mailer-channels",
)
s = replaceAllSafe(
  s,
  "list.funds.join(",
  "(list.funds||[]).join(",
  "mailer-funds",
)

// 9) Signature recipients defensive in key map sites (bridge also hardens)
s = replaceAllSafe(
  s,
  "e.recipients.map(",
  "(Array.isArray(e.recipients)?e.recipients:[]).map(",
  "recipients-map-guard",
)
s = replaceAllSafe(
  s,
  "envelope.recipients.map(",
  "(Array.isArray(envelope.recipients)?envelope.recipients:[]).map(",
  "envelope-recipients-map",
)
s = replaceAllSafe(
  s,
  "envelope?.recipients.map(",
  "(Array.isArray(envelope?.recipients)?envelope.recipients:[]).map(",
  "envelope-opt-recipients-map",
)

fs.writeFileSync(RUNTIME, s)
console.log("patched", RUNTIME, "bytes", Buffer.byteLength(s))
console.log("OK — re-run after every extract-portfolio-v25.mjs")
